import json
import os
from pathlib import Path
from typing import Any, Dict, List, Union

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _read_document_bytes(document: Union[str, bytes, bytearray, Path]) -> bytes:
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)

    if isinstance(document, Path):
        return document.read_bytes()

    if isinstance(document, str):
        if document.startswith(("http://", "https://")):
            import requests

            resp = requests.get(document, timeout=60)
            resp.raise_for_status()
            return resp.content
        return Path(document).expanduser().read_bytes()

    raise TypeError("document must be a file path, URL, bytes, or bytearray")


def _normalize_field_value(field: Any) -> Any:
    if field is None:
        return None

    value_type = getattr(field, "value_type", None)

    if value_type == "string":
        return getattr(field, "value_string", None)
    if value_type == "date":
        return str(getattr(field, "value_date", None)) if getattr(field, "value_date", None) else None
    if value_type == "time":
        return str(getattr(field, "value_time", None)) if getattr(field, "value_time", None) else None
    if value_type == "phoneNumber":
        return getattr(field, "value_phone_number", None)
    if value_type == "number":
        return getattr(field, "value_number", None)
    if value_type == "integer":
        return getattr(field, "value_integer", None)
    if value_type == "selectionMark":
        return getattr(field, "value_selection_mark", None)
    if value_type == "countryRegion":
        return getattr(field, "value_country_region", None)
    if value_type == "currency":
        currency = getattr(field, "value_currency", None)
        if currency is None:
            return None
        return {
            "amount": getattr(currency, "amount", None),
            "currency_symbol": getattr(currency, "symbol", None),
            "currency_code": getattr(currency, "code", None),
        }
    if value_type == "address":
        addr = getattr(field, "value_address", None)
        if addr is None:
            return None
        return {
            "street_address": getattr(addr, "street_address", None),
            "city": getattr(addr, "city", None),
            "state": getattr(addr, "state", None),
            "postal_code": getattr(addr, "postal_code", None),
            "country_region": getattr(addr, "country_region", None),
            "house_number": getattr(addr, "house_number", None),
            "po_box": getattr(addr, "po_box", None),
            "road": getattr(addr, "road", None),
            "unit": getattr(addr, "unit", None),
        }
    if value_type == "array":
        items = getattr(field, "value_array", None) or []
        return [_normalize_field_value(item) for item in items]
    if value_type == "object":
        obj = getattr(field, "value_object", None) or {}
        return {k: _normalize_field_value(v) for k, v in obj.items()}
    if value_type == "signature":
        return getattr(field, "content", None)
    if value_type == "boolean":
        return getattr(field, "value_boolean", None)

    for attr in (
        "value_string",
        "value_date",
        "value_time",
        "value_phone_number",
        "value_number",
        "value_integer",
        "value_selection_mark",
        "value_country_region",
        "value_boolean",
    ):
        if hasattr(field, attr):
            val = getattr(field, attr)
            if val is not None:
                return val

    content = getattr(field, "content", None)
    if content is not None:
        return content

    return None


def extract_key_value_pairs(document: Union[str, bytes, bytearray, Path]) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    data = _read_document_bytes(document)

    poller = client.begin_analyze_document(
        model_id="prebuilt-document",
        analyze_request=data,
        content_type="application/octet-stream",
    )
    result = poller.result()

    extracted: Dict[str, Any] = {
        "key_value_pairs": [],
        "documents": [],
        "tables": [],
        "pages": [],
    }

    kvps: List[Dict[str, Any]] = []
    for pair in getattr(result, "key_value_pairs", []) or []:
        key_obj = getattr(pair, "key", None)
        value_obj = getattr(pair, "value", None)

        kvps.append(
            {
                "key": getattr(key_obj, "content", None) if key_obj else None,
                "value": _normalize_field_value(value_obj),
                "confidence": getattr(pair, "confidence", None),
                "key_spans": [
                    {
                        "offset": span.offset,
                        "length": span.length,
                    }
                    for span in (getattr(key_obj, "spans", []) or [])
                ]
                if key_obj
                else [],
                "value_spans": [
                    {
                        "offset": span.offset,
                        "length": span.length,
                    }
                    for span in (getattr(value_obj, "spans", []) or [])
                ]
                if value_obj
                else [],
            }
        )

    extracted["key_value_pairs"] = kvps

    docs = []
    for doc in getattr(result, "documents", []) or []:
        fields = getattr(doc, "fields", {}) or {}
        docs.append(
            {
                "doc_type": getattr(doc, "doc_type", None),
                "confidence": getattr(doc, "confidence", None),
                "fields": {name: _normalize_field_value(field) for name, field in fields.items()},
            }
        )
    extracted["documents"] = docs

    tables = []
    for table in getattr(result, "tables", []) or []:
        cells = []
        for cell in getattr(table, "cells", []) or []:
            cells.append(
                {
                    "row_index": getattr(cell, "row_index", None),
                    "column_index": getattr(cell, "column_index", None),
                    "content": getattr(cell, "content", None),
                    "kind": getattr(cell, "kind", None),
                    "row_span": getattr(cell, "row_span", None),
                    "column_span": getattr(cell, "column_span", None),
                    "confidence": getattr(cell, "confidence", None),
                }
            )
        tables.append(
            {
                "row_count": getattr(table, "row_count", None),
                "column_count": getattr(table, "column_count", None),
                "cells": cells,
            }
        )
    extracted["tables"] = tables

    pages = []
    for page in getattr(result, "pages", []) or []:
        lines = []
        for line in getattr(page, "lines", []) or []:
            lines.append(
                {
                    "content": getattr(line, "content", None),
                    "polygon": [
                        {"x": p.x, "y": p.y}
                        for p in (getattr(line, "polygon", []) or [])
                    ],
                }
            )
        pages.append(
            {
                "page_number": getattr(page, "page_number", None),
                "width": getattr(page, "width", None),
                "height": getattr(page, "height", None),
                "unit": getattr(page, "unit", None),
                "lines": lines,
            }
        )
    extracted["pages"] = pages

    return extracted


def main() -> None:
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("Usage: python script.py <document_path_or_url>")

    result = extract_key_value_pairs(sys.argv[1])
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
